static void inputCaptureShutdown() {
    onexX2OwnerStop();
    {
        std::lock_guard<std::mutex> tickLock(g_inputCaptureBusTickMx);
        inputCaptureWindowsProcessingRetire();
        oemVendorHidShutdown();
        inputCaptureLegionMotionSessionRevoke();
    }
    if (!g_inputCaptureReady) return;
    inputCaptureDrainQueuedSamples();
    inputCaptureAppend({{"t", (unsigned long long)GetTickCount64()}, {"kind", "stop"}});
    {
        std::lock_guard<std::mutex> lock(g_inputCaptureMx);
        if (g_inputCaptureLog.is_open()) {
            g_inputCaptureLog.flush();
            g_inputCaptureLog.close();
        }
        g_inputCaptureSampleWrites = 0;
    }
    // 传感器对象在专职 STA 线程释放（HC StopListening），随后收尾线程。
    const bool sensorOwnerSettled=inputCaptureSensorThreadShutdown();
    g_inputCaptureSensorsSuspended = false;
    if(sensorOwnerSettled) g_inputCaptureSink.reset();
    if (g_gmDll) {
        if (g_gm) {
            auto del = (GmDelete)GetProcAddress(g_gmDll, "DeleteGamepadMotion");
            if (del) del(g_gm);
            g_gm = nullptr;
        }
        // The independent controller owner has already retired above. A failed
        // Windows Create must not leak this DLL reference on normal shutdown.
        FreeLibrary(g_gmDll); g_gmDll = nullptr;
    }
    g_gmPlayer = nullptr;
    g_gmWorld = nullptr;
    g_gmProcess = nullptr;
    g_gmGetCal = nullptr;
    g_gmGetGravity = nullptr;
    g_gmGetProcessedAcceleration = nullptr;
    g_gmGetOrientation = nullptr;
    g_gmGetOffset = nullptr;
    g_gmGetConf = nullptr;
    g_gmIsSteady = nullptr;
    g_gmSetMode = nullptr;
    g_gmStartCal = nullptr;
    g_gmPauseCal = nullptr;
    g_gmResetCal = nullptr;
    g_gmSetOffset = nullptr;
    g_gmResetMotionApi = nullptr;
    g_controllerGmCreate = nullptr;
    g_controllerGmDelete = nullptr;
    g_inputCaptureReady = false;
    const InputHostVirtualIntentMutation intentMutation;
    g_realStickTest = {};
    g_realStickTestAdmissionLogged = false;
}

initPrefix.text:
static void inputCaptureInit() {
    // New-process static initialization supplies the open fence. This delayed
    // worker may only initialize diagnostics; an observed app-exit fence stays raised.
    inputHostResetExitFence("capture-init");
    if (g_inputCaptureReady) return;
    if (!inputCaptureAssetsPresent()) {
        writeLog("INFO", "input-capture skipped: no gyro-motion/virtual-gamepad folders");
        publishStartupInputState(ymcc::StartupInputState::Failed, "input-assets-unavailable");
        return;
    }
    // 7.50 i2：DSU UDP 服务随 capture 启动（HC DSUServer.Start 在 VirtualManager
    // 打开虚拟手柄时；此处 feature 存在即启动以便 DSU 客户端随时连接）。
    if (dsu_start())
        appendNativeLifecycleLog("dsu-server-started", {{"port", 26760}, {"protocol", "dsu-1001"}});

resetFence.text:
static void inputHostResetExitFence(const char* owner) {
    // The process default is open. Capture initialization may reset diagnostic
    // counters, but must never reopen a terminal fence raised by app exit.
    const bool previousRaised = g_inputHostExitFence.load(std::memory_order_acquire);
    if (previousRaised) {
        appendNativeLifecycleLog("input-host-exit-fence", {
            {"phase", "reset-refused"}, {"reason", "terminal-process-exit"},
            {"previousRaised", true}, {"owner", owner ? owner : "unknown"},
            {"refusals", g_inputHostExitFenceRefusals.load(std::memory_order_acquire)}
        });
        return;
    }
    g_inputHostExitFenceRefusals.store(0, std::memory_order_release);
    g_inputHostExitFenceRefusalRows.store(0, std::memory_order_release);
    appendNativeLifecycleLog("input-host-exit-fence", {
        {"phase", "reset"},
        {"resetScope", "diagnostic-counters-only"},
        {"previousRaised", previousRaised},
        {"owner", owner ? owner : "unknown"},
        {"refusals", 0ULL}
    });
}
